"use strict";
// The piece names are read from text, so the package's own calls pass values
// that no call site types.
const PIECES = JSON.parse('["bowl","cup","jug","urn"]');

function fire(options) {
  const glaze =
    options.glaze === undefined ? (piece, finish) => piece + "~" + String(finish) : options.glaze;
  options.note("fired");
  return [
    glaze(PIECES[0]),
    glaze(PIECES[1], undefined),
    glaze(PIECES[2], options.label),
    glaze(PIECES[3], "tin", 3),
  ].join(" ");
}

class Tongs {
  constructor(grip) {
    this.grip = grip;
  }
  hold(piece) {
    return piece + "@" + this.grip;
  }
}

function lift(options) {
  const carry = options.carry;
  const tongs = new Tongs(4);
  return carry === undefined
    ? "left on the shelf"
    : [carry(tongs), carry(tongs, undefined), carry(tongs, "slowly")].join(" ");
}

exports.fire = fire;
exports.lift = lift;
exports.Tongs = Tongs;
